 */
indexOf(row) {
  let rowIndex = 0;
  for (const childRow of this.children) {
    if (childRow == row) {
      return rowIndex;
    }
    rowIndex++;
    if (childRow.open) {
      const childIndex = childRow.indexOf(row);
      if (childIndex >= 0) {
        return rowIndex + childIndex;
      }
      rowIndex + childRow.rowCount;
    }
  }
  return -1;
}

